      const body = await rawSearch(term);
      if (!body || !body.hits || !Array.isArray(body.hits.hits)) {
        return { matched: [] };
      }
      const matched = body.hits.hits
        .map(hitToRecord)
        .filter((r) => r !== null);
      return { matched };
    }, timeoutMs, options.clock);
  }

  return { search, rawSearch };
}

