  const setT = clock.setTimeout || setTimeout;
  const clearT = clock.clearTimeout || clearTimeout;

  return new Promise((resolve) => {
    let done = false;
    const timer = setT(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);

    Promise.resolve()
      .then(operation)
      .then((value) => {
        if (!done) {
          done = true;
          clearT(timer);
          resolve(value);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearT(timer);
          resolve(undefined);
