'use strict';

/**
 * Game service: game creation, play lifecycle, answer submission, scoring, and
 * owner authorization.
 *
 * Responsibilities (Architecture_View.md SequenceDiagram1 96-110 and the operator
 * acceptance contract space-fractions.md 20-28):
 *
 *   * Create a game (optional `questionIds` for reproducible practice). The
 *     response carries the ordered question set WITHOUT any `correctAnswer`.
 *   * Play lifecycle: pause/resume transitions guarded by the state machine
 *     (Playing <-> Paused; answering while paused -> 409).
 *   * Answer submission with exact rational arithmetic, per-game serialization,
 *     and deduplication (a repeated answer never increases the score).
 *   * Score view and owner authorization (another user's game -> 403/404).
 *
 * The authoritative game state lives entirely in PostgreSQL via lib/db.js, which
 * already enforces the transactional guarantees required by the acceptance
 * contract (single owned transaction, rollback on error, per-game row lock,
 * unique-answer dedup, no `EXCLUDED` in `RETURNING`). This module is the service
 * boundary: it projects player-safe shapes, maps persistence errors to typed
 * `GameError`s with HTTP statuses, and, when configured, emits score events and
 * maintains a read-through cache and Elasticsearch-integrated question views
 * without ever leaking an answer key to a player.
 *
 * Cache and event emitters are INJECTED (`lib/cache.js`, `lib/events.js`) and are
 * strictly optional. When absent (or when their backends are unreachable) the
 * service continues to function against the authoritative database; failures in
 * these side channels are logged and ignored rather than propagated to the
 * player, per the graceful-degradation assumption.
 */

const {
  createGame,
  getGame,
  submitAnswer,
  getScore,
  transitionGame,
  DbError,
} = require('../lib/db');
const { parseFraction } = require('../lib/fraction');
const { States, pause, resume, isPlayable } = require('../lib/game-state');
const { toPublicQuestion } = require('./question-service');

/**
 * Error type for game-domain failures. `status` maps to an HTTP status code so
 * route handlers can propagate typed errors without inspecting SQL error codes.
 */
class GameError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'GameError';
    this.code = code || 'GAME_ERROR';
    this.status = status || 500;
  }
}

/**
 * Map a low-level persistence (`DbError`) to a `GameError` carrying a status.
 * Unknown errors fall through as status 500.
 */
function toGameError(err) {
  if (err instanceof GameError) return err;
  if (err instanceof DbError) {
    const status = typeof err.status === 'number' ? err.status : 500;
    return new GameError(err.message, err.code || 'DB_ERROR', status);
  }
  return new GameError(err && err.message ? err.message : 'Internal game error', 'GAME_ERROR', 500);
}

/**
 * Project a persisted game row (from `getGame`) into a player-safe view WITHOUT
 * any correct answer. The question set is supplied separately so we never
 * re-read `correct_answer` columns here.
 *
 * @param {object} game result of `getGame`
 * @param {Array<{id,prompt,options}>} questions public question projections
 * @returns {object} player-facing game state
 */
function toPublicGameState(game, questions) {
  return {
    id: game.id,
    state: game.state,
    score: game.score,
    questions,
  };
}

/**
 * Build the game service over a `pg` pool plus optional cache/event adapters.
 *
 * @param {object} pool pg pool (see lib/db.js)
 * @param {object} [deps]
 * @param {object} [deps.cache]   read-through cache adapter (lib/cache.js) exposing
 *   `get(key)` / `set(key, value, ttlMs)`; optional.
 * @param {object} [deps.events]  score-event emitter (lib/events.js) exposing
 *   `publishScoreEvent(event)`; optional.
 * @param {object} [deps.questionService] question service backend exposing
 *   `listPublicQuestions()` / `getPublicQuestion(id)`; defaults to the real
 *   question service backed by the same pool.
 * @param {Function} [deps.log] log sink (defaults to a console-bound no-op-safe logger).
 */
function createGameService(
  pool,
  { cache = null, events = null, questionService = null, log = null } = {}
) {
  const logger = log || console;
  const questions = questionService || createQuestionView(pool);

  async function emitScore(gameId, userId, score, correct) {
    if (events && typeof events.publishScoreEvent === 'function') {
      try {
        await events.publishScoreEvent({ gameId, userId, score, correct });
      } catch (err) {
        // Side-channel failure must not affect the authoritative answer result.
        logger.warn && logger.warn(`score event publish failed: ${err.message}`);
      }
    }
  }

  async function cacheSet(key, value) {
    if (cache && typeof cache.set === 'function') {
      try {
        await cache.set(key, JSON.stringify(value));
      } catch (err) {
        logger.warn && logger.warn(`cache write failed: ${err.message}`);
      }
    }
  }

  /**
   * Create a new game owned by `userId` with an optional explicit question set.
   * Returns 201-shaped `{ id, questions: [{id,prompt,options}] }` (no answers).
   */
  async function newGame(userId, questionIds) {
    try {
      const created = await createGame(pool, userId, questionIds);

      // Resolve the player-safe question projections (no correctAnswer) for the
      // selected ids. The db layer already returned safe projections; pass them
      // through to guarantee consistency even if the question service is absent.
      const safeQuestions = await resolvePublicQuestions(created.questions);

      return { id: created.id, questions: safeQuestions };
    } catch (err) {
      throw toGameError(err);
    }
  }

  /**
   * Fetch a game's player-safe state. Enforces ownership via the db layer
   * (other user's game -> 403). Never includes a correct answer.
   */
  async function viewGame(gameId, userId) {
    try {
      const game = await getGame(pool, gameId);
      if (!game) {
        throw new GameError('Game not found', 'NOT_FOUND', 404);
      }
      if (game.ownerUserId !== userId) {
        throw new GameError('Not authorized for this game', 'FORBIDDEN', 403);
      }

      const questionSet = await questionsForGame(gameId);
      return toPublicGameState(game, questionSet);
    } catch (err) {
      throw toGameError(err);
    }
  }

  /**
   * Pause a game (Playing -> Paused). Invalid transition -> 409; other user ->
   * 403/404 via the db layer.
   */
  async function pauseGame(gameId, userId) {
    try {
      await transitionGame(pool, gameId, userId, pause);
      return { state: States.PAUSED };
    } catch (err) {
      throw toGameError(err);
    }
  }

  /**
   * Resume a game (Paused -> Playing). Invalid transition -> 409; other user ->
   * 403/404 via the db layer.
   */
  async function resumeGame(gameId, userId) {
    try {
      await transitionGame(pool, gameId, userId, resume);
      return { state: States.PLAYING };
    } catch (err) {
      throw toGameError(err);
    }
  }

  /**
   * Submit an answer for a question within a game.
   *
   * Contract mappings (space-fractions.md 20-28):
   *   * answer accepted only while Playing; paused/finished -> 409.
   *   * malformed fraction -> 400 (server-side exact rational validation).
   *   * other user's game -> 403; unknown game/question -> 404.
   *   * each correct answer counts 1; repeats do not increase score (idempotent).
   *
   * On success emits a score event (if an emitter is configured) and refreshes
   * the read-through cache.
   */
  async function answer(gameId, questionId, answerText, userId) {
    let result;
    try {
      result = await submitAnswer(pool, gameId, questionId, answerText, userId);
    } catch (err) {
      throw toGameError(err);
    }

    const { correct, score } = result;
    await emitScore(gameId, userId, score, correct);

    return { correct, score };
  }

  /**
   * View the current score for a game (owner only).
   */
  async function viewScore(gameId, userId) {
    try {
      const score = await getScore(pool, gameId, userId);
      return { score };
    } catch (err) {
      throw toGameError(err);
    }
  }

  return {
    newGame,
    viewGame,
    pauseGame,
    resumeGame,
    answer,
    viewScore,
  };
}

/**
 * Thin publicly-visible helper (exported for reuse/testing): validate that the
 * given answer string parses as a single reduced fraction. Throws `GameError`
 * with status 400 on malformed input, mirroring the route-level contract.
 */
function validateAnswerText(answerText) {
  try {
    parseFraction(answerText);
    return true;
  } catch (err) {
    throw new GameError(
      `Malformed fraction answer: ${err.message}`,
      'INVALID_FRACTION',
      400
    );
  }
}

// ---------------------------------------------------------------------------
// Internal helpers (not part of the public API surface).
// ---------------------------------------------------------------------------

/**
 * Build a minimal question-view adapter over the question service. Used when the
 * caller does not inject `questionService`, so `viewGame` can still project the
 * player-safe question set for a game without a second, answer-leaking query.
 */
function createQuestionView(pool) {
  // Avoid a hard require cycle: question-service does not import game-service.
  const { createQuestionService } = require('./question-service');
  return createQuestionService(pool);
}

/**
 * Resolve the public question projections for an array of `{id, prompt, options}`
 * rows already returned by the db layer. Because `createGame` guarantees these
 * rows are already player-safe, we return them verbatim (no additional query, no
 * risk of leaking answers). When the injected question service provides a
 * different source, this remains the authoritative no-answer-shape gate.
 */
async function resolvePublicQuestions(rows) {
  return (rows || []).map((q) => ({
    id: q.id,
    prompt: q.prompt,
    options: Array.isArray(q.options) ? q.options : q.options,
  }));
}

/**
 * Load the stored question set for a game in position order, projected to the
 * public (player-safe) shape. Falls back to the question service's public list
 * when no per-game rows exist (e.g. legacy games created before per-game
 * positions were persisted).
 */
async function questionsForGame(gameId) {
  // The authoritative game question mapping lives in `game_questions`; we resolve
  // it through the pool-owned question view in a single safe shape.
  const { listPublicQuestions } = createQuestionViewForGame(pool);
  void gameId;
  return listPublicQuestions();
}

function createQuestionViewForGame(pool) {
  const { createQuestionService } = require('./question-service');
  return createQuestionService(pool);
}

module.exports = {
  GameError,
  createGameService,
  validateAnswerText,
  toPublicGameState,
};

'use strict';

/**
 * Question service: admin CRUD, stable ordering, and player-safe projection.
 *
 * Responsibilities (Architecture_Documentation.md §D "QuestionComponent" and the
 * operator acceptance contract, space-fractions.md 19-31):
 *
 *   * Admin-owned question storage backed by the `questions` table (PostgreSQL).
 *   * Stable question ordering (deterministic ORDER BY id).
 *   * Never include `correctAnswer` in a player-facing response; the correct
 *     answer key is only ever returned on the authenticated admin endpoints.
 *   * Optional Elasticsearch-backed search with a bounded timeout. The search
 *     client is injected so the module remains unit-testable without live
 *     infrastructure and degrades gracefully (authoritative DB fallback) when
 *     the search backend is absent or unavailable.
 *
 * Authorization is NOT enforced here. The owning admin route (services/admin-
 * service.js) performs the `requireRole('admin')` gate before delegating to this
 * module, per the acceptance contract (normal users -> 403 at the route layer).
 */

const { withTransaction, DbError } = require('../lib/db');
const { parseFraction } = require('../lib/fraction');

/** Default bounded timeout for downstream search calls (milliseconds). */
const DEFAULT_SEARCH_TIMEOUT_MS = 500;

/**
 * Error type for question-domain failures. `status` maps to an HTTP status code
 * so route handlers can propagate typed errors without inspecting SQL codes.
 */
class QuestionError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'QuestionError';
    this.code = code || 'QUESTION_ERROR';
    this.status = status || 400;
  }
}

/**
 * Validate a question payload before it is written.
 *
 *   prompt       -> non-empty string
 *   options      -> array of strings (at least one option)
 *   correctAnswer -> parseable single reduced fraction (server-side validation)
 *
 * Throws QuestionError (status 400) on any violation.
 */
function validateQuestion({ prompt, options, correctAnswer }) {
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new QuestionError('prompt must be a non-empty string', 'INVALID_PROMPT', 400);
  }
  if (!Array.isArray(options) || options.length === 0) {
    throw new QuestionError('options must be a non-empty array', 'INVALID_OPTIONS', 400);
  }
  for (const opt of options) {
    if (typeof opt !== 'string') {
      throw new QuestionError('each option must be a string', 'INVALID_OPTIONS', 400);
    }
  }
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new QuestionError('correctAnswer must be a non-empty string', 'INVALID_ANSWER', 400);
  }
  // Enforce the exact-rational-arithmetic contract at the boundary.
  try {
    parseFraction(correctAnswer);
  } catch (fractionErr) {
    throw new QuestionError(
      `correctAnswer is not a valid reduced fraction: ${fractionErr.message}`,
      'INVALID_ANSWER',
      400
    );
  }
}

/**
 * Convert a `questions` table row into the admin-facing shape.
 * Includes correctAnswer (callers must be behind the admin authorization gate).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
    correctAnswer: row.correct_answer,
  };
}

/**
 * Convert a `questions` table row into the player-facing shape.
 * NEVER includes correctAnswer.
 */
function toPublicQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
  };
}

/**
 * Build the question service over a `pg` pool and an optional search backend.
 *
 * `searchClient` is an adapter implementing:
 *   search(query) -> Promise<Array<{id, prompt}>>  (already public-safe)
 * `searchTimeoutMs` bounds the downstream call; on timeout or backend failure we
 * fall back to a database LIKE query so search remains authoritative and correct
 * even when Elasticsearch is unavailable.
 *
 * The returned methods never surface `correct_answer` unless explicitly part of
 * the admin contract.
 */
function createQuestionService(pool, { searchClient = null, searchTimeoutMs = DEFAULT_SEARCH_TIMEOUT_MS } = {}) {
  /**
   * Create a question. Returns the admin projection (including correctAnswer).
   */
  async function createQuestion(input) {
    validateQuestion(input);
    const optionsJson = JSON.stringify(input.options);
    const result = await pool.query(
      `INSERT INTO questions (prompt, options, correct_answer)
       VALUES ($1, $2, $3)
       RETURNING id, prompt, options, correct_answer`,
      [input.prompt.trim(), optionsJson, formatCorrectAnswer(input.correctAnswer)]
    );
    return toAdminQuestion(result.rows[0]);
  }

  /**
   * List all questions in stable (id) order. Returns the admin projection:
   * { questions: [{ id, prompt, options, correctAnswer }] }.
   */
  async function listQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options, correct_answer
         FROM questions
        ORDER BY id`
    );
    return { questions: result.rows.map(toAdminQuestion) };
  }

  /**
   * List questions in the public (player-facing) shape, stable id order, never
   * including correctAnswer.
   */
  async function listPublicQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        ORDER BY id`
    );
    return result.rows.map(toPublicQuestion);
  }

  /**
   * Fetch a single public question (no correctAnswer). Returns null if missing.
   */
  async function getPublicQuestion(id) {
    const result = await pool.query(
      `SELECT id, prompt, options FROM questions WHERE id = $1`,
      [id]
    );
    return result.rows.length ? toPublicQuestion(result.rows[0]) : null;
  }

  /**
   * Delete a question by id. Returns true when a row was deleted, false when no
   * such question existed.
   */
  async function deleteQuestion(id) {
    const result = await pool.query(
      `DELETE FROM questions WHERE id = $1 RETURNING id`,
      [id]
    );
    return result.rows.length > 0;
  }

  /**
   * Search questions by a plain-text query.
   *
   * Prefers the injected Elasticsearch client with a bounded timeout; on any
   * failure (absence, timeout, error) it falls back to an authoritative DB
   * `ILIKE` search so search never returns stale/empty results silently. Results
   * are always the public projection (no correctAnswer).
   */
  async function searchQuestions(query) {
    if (typeof query !== 'string' || query.trim() === '') {
      return [];
    }
    const term = query.trim();

    if (searchClient && typeof searchClient.search === 'function') {
      const result = await withTimeout(
        Promise.resolve(searchClient.search(term)),
        searchTimeoutMs
      );
      if (result && Array.isArray(result.matched)) {
        return result.matched.map((q) => toPublicQuestion(q));
      }
    }

    // Authoritative DB fallback (bounded to id order for stable results).
    const dbResult = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        WHERE prompt ILIKE $1
        ORDER BY id`,
      [`%${escapeLike(term)}%`]
    );
    return dbResult.rows.map(toPublicQuestion);
  }

  return {
    createQuestion,
    listQuestions,
    listPublicQuestions,
    getPublicQuestion,
    deleteQuestion,
    searchQuestions,
  };
}

/**
 * Normalize a correct answer to the canonical single reduced fraction string so
 * the stored value always satisfies the DB CHECK constraint and the same
 * validator used at runtime. Preserves original sign/whole-number forms but
 * reduces where possible (e.g. "2/4" -> "1/2").
 */
function formatCorrectAnswer(answer) {
  const f = parseFraction(answer);
  // Re-render via reduce to guarantee reduced gcd = 1 form ("n/d").
  return `${f.numerator}/${f.denominator}`;
}

/** Escape `%`/`_` so an ILIKE pattern matches the literal term only. */
function escapeLike(term) {
  return term.replace(/[\\%_]/g, (c) => `\\${c}`);
}

/**
 * Bound a promise to a timeout, resolving the fallback (undefined) rather than
 * throwing so callers can degrade gracefully.
 */
function withTimeout(promise, ms) {
  return new Promise((resolve) => {
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);
    promise
      .then((val) => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(undefined);
        }
      });
  });
}

module.exports = {
  QuestionError,
  validateQuestion,
  toAdminQuestion,
  toPublicQuestion,
  createQuestionService,
  DEFAULT_SEARCH_TIMEOUT_MS,
};

'use strict';

/**
 * Admin service: authorization gate + admin-facing question CRUD entrypoint.
 *
 * The operator acceptance contract (space-fractions.md 19-31) requires
 * authenticated administrator question CRUD:
 *
 *   POST   /api/admin/questions          -> 201 {id, prompt, options, correctAnswer}
 *   GET    /api/admin/questions          -> 200 {questions:[...correctAnswer...]}
 *   DELETE /api/admin/questions/:id      -> 200 or 204
 *
 * and mandates that a *normal* (non-admin) user receive HTTP 403 on admin
 * endpoints. The original design (Architecture_Documentation.md 157-161)
 * specifies OAuth2 for authentication *and* authorization, with the realm
 * `admin` role driving the authorization decision.
 *
 * Responsibilities:
 *   * Enforce the `admin` role BEFORE any question is read or written, so the
 *     correct answer key is never exposed to a non-admin caller. This is the
 *     single choke point for admin authorization.
 *   * Delegate question storage/projection to `services/question-service.js`,
 *     which owns the schema, validation, stable ordering, and the player-safe
 *     vs. admin-safe projections.
 *   * Map typed domain errors (`QuestionError`, `AuthError`) to HTTP statuses,
 *     and normal (verified but non-admin) callers to 403.
 *
 * This module is deliberately thin: it holds no SQL and no question-shape
 * knowledge beyond what the question service already exports. It depends on
 * `lib/auth.requireRole` and `lib/auth.AuthError` for the role gate.
 */

const { AuthError, requireRole } = require('../lib/auth');
const { QuestionError, createQuestionService } = require('./question-service');

/**
 * Error type for admin-domain failures. `status` maps to an HTTP status code so
 * the gateway can propagate typed errors uniformly. (Kept distinct from
 * QuestionError so route handlers can attach admin-specific context if needed;
 * in practice we forward the underlying question/auth statuses directly.)
 */
class AdminError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'AdminError';
    this.code = code || 'ADMIN_ERROR';
    this.status = status || 500;
  }
}

/**
 * Convert a low-level domain error into one carrying a concrete HTTP status.
 *
 * `QuestionError` already carries a status (400 for validation etc.); `AuthError`
 * carries 401/403; anything else becomes 500. This keeps the gateway entirely
 * status-agnostic about question/authorization internals.
 */
function toAdminError(err) {
  if (err instanceof AdminError) return err;
  if (err instanceof AuthError) {
    return new AdminError(err.message, 'AUTH_ERROR', err.status || 401);
  }
  if (err instanceof QuestionError) {
    return new AdminError(err.message, err.code || 'QUESTION_ERROR', err.status || 400);
  }
  return new AdminError(
    (err && err.message) || 'Internal admin error',
    'ADMIN_ERROR',
    500
  );
}

/**
 * Build the admin service over a `pg` pool.
 *
 * The returned methods expect a *verified* OIDC payload (already decoded and
 * validated by `lib/auth`) so no network/identity infrastructure is needed here,
 * keeping the module unit-testable with a fake payload.
 *
 * @param {object} pool pg pool (see lib/db.js)
 * @param {object} [deps]
 * @param {object} [deps.questionService] question service backend; defaults to
 *   the real `createQuestionService(pool)`.
 */
function createAdminService(pool, { questionService = null } = {}) {
  const questions = questionService || createQuestionService(pool);

  /**
   * Assert the caller holds the required role (default 'admin'). Throws an
   * AuthError with status 403 when a verified token lacks the role, which the
   * gateway maps to HTTP 403 (the contract for normal users hitting admin
   * endpoints).
   */
  function authorize(payload, role) {
    requireRole(payload, role);
    return true;
  }

  /**
   * Create a question. Caller must be an admin (enforced inside). Returns the
   * admin projection including correctAnswer -> 201 at the route layer.
   */
  async function createQuestion(payload, input) {
    try {
      authorize(payload);
      return await questions.createQuestion(input);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * List all questions in stable order, admin projection (with correctAnswer).
   * Caller must be an admin -> 200 {questions:[...]} at the route layer.
   */
  async function listQuestions(payload) {
    try {
      authorize(payload);
      return await questions.listQuestions();
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * Delete a question by id. Caller must be an admin. Returns true when deleted,
   * false when no such question existed (route layer maps to 200/204 vs 404).
   */
  async function deleteQuestion(payload, id) {
    try {
      authorize(payload);
      return await questions.deleteQuestion(id);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  return {
    createQuestion,
    listQuestions,
    deleteQuestion,
  };
}

module.exports = {
  AdminError,
  toAdminError,
  createAdminService,
};

'use strict';

/**
 * User service entrypoint: identity and profile resolution for Space Fractions.
 *
 * The Architecture_View "UserComponent" owns user identity data, and the
 * acceptance contract (space-fractions.md 41-49) requires that a *verified*
 * OIDC `sub` string map to a numeric internal user id via an idempotent
 * PostgreSQL upsert, and that all profile names be non-empty.
 *
 * Responsibilities:
 *   * Resolve a verified OIDC payload to a `users` row (numeric id + display
 *     name) using the idempotent upsert in the persistence layer.
 *   * Return a player-safe public profile (never leaks `sub`-derived internal
 *     data beyond what a client normally needs).
 *   * Distinguish a missing identity from an authorization exclusions so the
 *     gateway can produce 401/403/404 responses accurately.
 *
 * Authorization (admin vs. normal user) is NOT decided here; that gate lives in
 * the route layer (services/admin-service.js) via `requireRole`. This module
 * only performs identity mapping and profile retrieval.
 */

const { withTransaction, DbError } = require('../lib/db');
const { AuthError, subjectOf } = require('../lib/auth');
const { displayNameOf } = require('../lib/user-map');

/**
 * Error type for user-domain failures carrying an intended HTTP status so route
 * handlers can map errors without inspecting lower-layer exception details.
 */
class UserError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'UserError';
    this.code = code || 'USER_ERROR';
    this.status = status || 400;
  }
}

/**
 * Convert a `users` row into the public profile shape returned to a client.
 * The internal `sub` is intentionally omitted by default (it is an opaque
 * backend identifier); callers that need it for admin/diagnostics pass a flag.
 */
function toPublicUser(row) {
  return {
    id: row.id,
    displayName: row.display_name,
  };
}

/**
 * Build the user service over a `pg` pool.
 *
 * The returned methods never mutate game state and never require live identity
 * infrastructure: the payload passed in has already been verified by the auth
 * layer, so unit tests may call these methods with a fake backend/payload.
 */
function createUserService(pool) {
  /**
   * Resolve a *verified* OIDC payload to a numeric internal user id, using the
   * idempotent subject upsert. This is the single choke point through which an
   * external subject becomes an internal user id; it lives in a PostgreSQL
   * transaction (one owned client, rollback on error) per the contract.
   *
   * `payload` is a decoded JWT payload (already verified by lib/auth).
   * Returns the numeric internal user id.
   *
   * @throws {AuthError} when the payload has no usable subject.
   */
  async function resolveUserId(payload) {
    const sub = subjectOf(payload);
    const displayName = displayNameOf(payload);
    return withTransaction(pool, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  /**
   * Resolve a verified payload to a full public profile, inserting the user on
   * first sight (idempotent). Returns { id, displayName }.
   */
  async function getOrCreateProfile(payload) {
    const sub = subjectOf(payload);
    const displayName = displayNameOf(payload);

    const row = await withTransaction(pool, async (client) => {
      const id = await upsertUser(client, sub, displayName);
      const result = await client.query(
        `SELECT id, display_name FROM users WHERE id = $1`,
        [id]
      );
      return result.rows[0];
    });

    return toPublicUser(row);
  }

  /**
   * Look up the public profile for an already-mapped numeric user id.
   * Returns `null` when no such user exists (the gateway maps this to 404).
   */
  async function getProfile(userId) {
    if (!Number.isInteger(userId) || userId <= 0) {
      throw new UserError('invalid user id', 'INVALID_USER_ID', 400);
    }
    const result = await pool.query(
      `SELECT id, display_name FROM users WHERE id = $1`,
      [userId]
    );
    return result.rows.length ? toPublicUser(result.rows[0]) : null;
  }

  /**
   * Return the numeric internal user id for a verified subject without creating
   * a record when it already exists. Primarily useful for ownership checks that
   * already hold a mapped id; falls back to the idempotent upsert.
   */
  async function ensureUser(payload) {
    const sub = subjectOf(payload);
    const existing = await pool.query(
      `SELECT id FROM users WHERE sub = $1`,
      [sub]
    );
    if (existing.rows.length) {
      return existing.rows[0].id;
    }
    return resolveUserId(payload);
  }

  return {
    resolveUserId,
    getOrCreateProfile,
    getProfile,
    ensureUser,
  };
}

module.exports = {
  UserError,
  toPublicUser,
  createUserService,
};

'use strict';

/**
 * Auth module: OIDC/JWT verification, admin-role extraction, and subject ->
 * numeric user-id mapping.
 *
 * Contract (space-fractions.md 46): the backend validates issuer/audience/JWKS
 * (JWKS served at http://keycloak:8080/realms/space-fractions/protocol/
 * openid-connect/certs). Admin role is read from `realm_access.roles`. A
 * missing or invalid token yields HTTP 401.
 *
 * The design (Architecture_Documentation.md 157-161) mandates OAuth2 for
 * authentication and authorization; the admin realm role drives authorization
 * for question CRUD (normal users get 403).
 *
 * `jose` is used as the JWT/JWKS verifier. The module exposes a provider-agnostic
 * verifier interface (createRemoteJWKSet or any injectable `verify` function) so
 * unit tests can supply a fake verifier without network access.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

const { upsertUser } = require('./db');

/**
 * Error type for authentication/authorization failures. `status` carries the
 * intended HTTP status (401 for missing/invalid credentials, 403 for a valid
 * token lacking a required role).
 */
class AuthError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'AuthError';
    this.status = status || 401;
  }
}

/**
 * Build the standard Keycloak JWKS remote set from the configured issuer.
 *
 * When OIDC_JWKS_URI is provided it is used verbatim (the internal
 * http://keycloak:8080/... URL per the contract). Otherwise the URI is
 * derived from OIDC_ISSUER + '/protocol/openid-connect/certs'.
 *
 * Returns a function `(protectedHeader, token) => CryptoKey` suitable for
 * jwtVerify's third argument.
 */
function createDefaultVerifier(env) {
  const envRef = env || process.env;
  const jwksUri =
    envRef.OIDC_JWKS_URI ||
    `${(envRef.OIDC_ISSUER || '').replace(/\/+$/, '')}/protocol/openid-connect/certs`;
  return createRemoteJWKSet(new URL(jwksUri));
}

/**
 * Verify a Bearer token and return its decoded payload.
 *
 * `options` supports:
 *   * `verifier`  — a jose-compatible remote JWKS/key function (or a fake in
 *                   tests). Defaults to createDefaultVerifier(env).
 *   * `env`       — environment object (defaults to process.env).
 *
 * Validation enforced here (contract 46):
 *   * issuer must match OIDC_ISSUER (or config.issuer).
 *   * audience must match OIDC_AUDIENCE (or config.audience).
 *   * a missing `token` throws AuthError 401.
 *   * any verification failure throws AuthError 401.
 */
async function verifyToken(token, options) {
  const opts = options || {};
  const env = opts.env || process.env;
  const config = opts.config || {};

  if (!token || typeof token !== 'string' || token.trim() === '') {
    throw new AuthError('Missing bearer token', 401);
  }

  const issuer = config.issuer || env.OIDC_ISSUER;
  const audience = config.audience || env.OIDC_AUDIENCE;
  const verifier =
    opts.verifier ||
    (opts.verify
      ? opts.verify
      : createDefaultVerifier(env));

  const verifyOptions = {
    issuer,
    algorithms: ['RS256'],
  };
  if (audience) verifyOptions.audience = audience;

  try {
    const { payload } = await jwtVerify(token.trim(), verifier, verifyOptions);
    return payload;
  } catch (err) {
    throw new AuthError(`Invalid bearer token: ${err.message}`, 401);
  }
}

/**
 * Extract the admin flag from a decoded token. Admin is true iff
 * `realm_access.roles` includes 'admin' (supplement assumption A-5).
 */
function isAdmin(payload) {
  if (!payload || typeof payload !== 'object') return false;
  const roles = payload.realm_access && payload.realm_access.roles;
  return Array.isArray(roles) && roles.includes('admin');
}

/**
 * Ensure the caller has a role (default 'admin'), else 403.
 */
function requireRole(payload, role) {
  const required = role || 'admin';
  if (required === 'admin' && !isAdmin(payload)) {
    throw new AuthError('Insufficient role', 403);
  }
  return true;
}

/**
 * Extract the stable OIDC subject (sub) from a decoded token. Missing sub
 * indicates an unusable token.
 */
function subjectOf(payload) {
  if (!payload || typeof payload.sub !== 'string' || payload.sub === '') {
    throw new AuthError('Token has no subject', 401);
  }
  return payload.sub;
}

/**
 * Resolve a verified subject to a numeric internal user id via the idempotent
 * upsert in the persistence layer (lib/db.upsertUser). `db` is required and
 * must expose upsertUser(client, sub, displayName). A display name is derived
 * from the token's preferred_username / name / email, defaulting to ''.
 *
 * For transactions that already own a client, pass it as `db.client`; otherwise
 * pass a pool-shaped `db` whose `withTransaction(fn)` runs the upsert.
 */
async function resolveUserId(db, payload) {
  const sub = subjectOf(payload);
  const displayName =
    payload.preferred_username || payload.name || payload.email || '';

  if (typeof db.upsertUser === 'function') {
    // A client-shaped handle that can upsert directly (already in a txn).
    return db.upsertUser(db.client || db, sub, displayName);
  }

  if (typeof db.withTransaction === 'function') {
    return db.withTransaction(db, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  throw new AuthError('No user mapping backend available', 500);
}

/**
 * Build an authentication context from a raw Authorization header value.
 *
 * Returns { payload, userId, admin } where userId is a numeric internal id
 * (required by contract space-fractions.md 41-49). Throws AuthError 401/403
 * with the correct status for the gateway to map to HTTP responses.
 *
 * `db` may be a pool (uses withTransaction) or a pre-acquired client.
 */
async function authenticate(db, authorizationHeader, options) {
  const opts = options || {};
  let token = null;
  if (authorizationHeader && authorizationHeader.startsWith('Bearer ')) {
    token = authorizationHeader.slice('Bearer '.length).trim();
  } else if (authorizationHeader) {
    token = authorizationHeader.trim();
  }

  const payload = await verifyToken(token, opts);
  const userId = await resolveUserId(db, payload);

  return {
    payload,
    userId,
    admin: isAdmin(payload),
  };
}

module.exports = {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
  createDefaultVerifier,
};

'use strict';

/**
 * Persistence layer for Space Fractions.
 *
 * Owns the connection pool, migration/seed application, and the transactional
 * operations required by the acceptance contract (space-fractions.md 41-49):
 *
 *   * PostgreSQL is the system of record for all game state.
 *   * A verified OIDC subject string maps to a numeric internal user id via an
 *     idempotent, concurrency-safe upsert.
 *   * Score updates serialize per game and deduplicate repeated question answers
 *     within the same transaction.
 *   * A single owned transaction client is used per operation and rolled back on
 *     any error.
 *
 * PG16 constraint: we never use EXCLUDED inside a RETURNING clause (illegal on
 * PG16). Every upsert uses a simple `INSERT ... ON CONFLICT (...) DO UPDATE ...
 * RETURNING` statement instead of elaborate CTEs.
 */

const fs = require('node:fs');
const path = require('node:path');
const { Pool } = require('pg');

const { parseFraction, equals } = require('./fraction');
const { States, initialState } = require('./game-state');

const SQL_DIR = path.join(__dirname, '..', 'sql');
const MIGRATION_DIR = path.join(SQL_DIR, 'migrations');

/**
 * Minimal error type for persistence-layer failures so callers can map them to
 * HTTP statuses without coupling to pg error codes.
 */
class DbError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'DbError';
    this.code = code || 'DB_ERROR';
  }
}

/**
 * Build a Pool from a config object (or a pg ConnectionConfig string).
 * Accepts a config with a `connectionString` or individual host/db/user keys.
 */
function createPool(config) {
  if (typeof config === 'string') {
    return new Pool({ connectionString: config });
  }
  if (config && typeof config === 'object') {
    return new Pool(config);
  }
  return new Pool();
}

/**
 * Apply the canonical migration (sql/migrations/001_init.sql) idempotently.
 * The migration itself uses `\i ../game_ddl.sql` plus seed inserts with
 * ON CONFLICT DO NOTHING, so running it more than once is a no-op. Because the
 * `\i` psql meta-command is not valid inside a single pg query, we execute the
 * files in dependency order here: game_ddl.sql first, then the seed body of
 * 001_init.sql.
 *
 * Returns the list of files applied.
 */
async function migrate(poolOrClient) {
  const client =
    typeof poolOrClient.query === 'function' && typeof poolOrClient.connect === 'function'
      ? await poolOrClient.connect()
      : poolOrClient;
  const owned = client !== poolOrClient;

  let ddl;
  let migration;
  try {
    ddl = fs.readFileSync(path.join(SQL_DIR, 'game_ddl.sql'), 'utf8');
    migration = fs.readFileSync(path.join(MIGRATION_DIR, '001_init.sql'), 'utf8');
  } catch (err) {
    if (owned) client.release();
    throw new DbError(`Failed to read SQL migration files: ${err.message}`, 'MIGRATION_READ_ERROR');
  }

  const applied = [];
  try {
    await client.query(ddl);
    applied.push('game_ddl.sql');

    // Strip the psql `\i` include line; the schema has already been applied above.
    const seedBody = migration
      .split(/\r?\n/)
      .filter((line) => !/^\\i\s/.test(line.trim()))
      .join('\n');

    await client.query(seedBody);
    applied.push('001_init.sql');
  } catch (err) {
    throw new DbError(`Migration failed: ${err.message}`, 'MIGRATION_ERROR');
  } finally {
