 * The migration itself uses `\i ../game_ddl.sql` plus seed inserts with
 * ON CONFLICT DO NOTHING, so running it more than once is a no-op. Because the
 * `\i` psql meta-command is not valid inside a single pg query, we execute the
 * files in dependency order here: game_ddl.sql first, then the seed body of
 * 001_init.sql.
 *
 * Returns the list of files applied.
 */
async function migrate(poolOrClient) {
  const client =
    typeof poolOrClient.query === 'function' && typeof poolOrClient.connect === 'function'
      ? await poolOrClient.connect()
      : poolOrClient;
  const owned = client !== poolOrClient;

  let ddl;
  let migration;
  try {
    ddl = fs.readFileSync(path.join(SQL_DIR, 'game_ddl.sql'), 'utf8');
    migration = fs.readFileSync(path.join(MIGRATION_DIR, '001_init.sql'), 'utf8');
  } catch (err) {
    if (owned) client.release();
    throw new DbError(`Failed to read SQL migration files: ${err.message}`, 'MIGRATION_READ_ERROR');
  }

  const applied = [];
  try {
    await client.query(ddl);
    applied.push('game_ddl.sql');

    // Strip the psql `\i` include line; the schema has already been applied above.
    const seedBody = migration
      .split(/\r?\n/)
      .filter((line) => !/^\\i\s/.test(line.trim()))
      .join('\n');

    await client.query(seedBody);
    applied.push('001_init.sql');
  } catch (err) {
    throw new DbError(`Migration failed: ${err.message}`, 'MIGRATION_ERROR');
  } finally {
    if (owned) client.release();
  }

  return applied;
}

/**
 * Upsert a verified OIDC subject and return its numeric internal user id.
 * Because users.sub is UNIQUE, concurrent calls for the same subject converge
 * to the same row id deterministically (no races, no duplicates).
 */
async function upsertUser(client, sub, displayName = '') {
  const result = await client.query(
    `INSERT INTO users (sub, display_name)
     VALUES ($1, $2)
     ON CONFLICT (sub) DO UPDATE SET display_name = EXCLUDED.display_name
     RETURNING id`,
    [sub, displayName]
  );
  return result.rows[0].id;
}

/**
 * Run `fn` inside a single owned transaction client. `fn(client)` receives the
 * transaction client and its return value is committed. On any error, the
 * transaction is rolled back and the client released before the error propagates.
 */
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  let released = false;
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (_rollbackErr) {
      /* best-effort rollback only */
    }
    throw err;
  } finally {
    client.release();
    released = true;
    void released;
  }
}

/**
 * Create a new game owned by `ownerUserId`. `questionIds` is an optional array;
 * when empty/undefined, draw from the seeded question bank in deterministic id
 * order. Persists the game row (game_state JSONB seeded with the Playing state)
 * and the stable, position-ordered question set in one transaction.
 *
 * Returns { id, questions } where questions is [{ id, prompt, options }] with no
 * correctAnswer (contract: never leak answers to players).
 */
async function createGame(pool, ownerUserId, questionIds) {
  return withTransaction(pool, async (client) => {
    const { rows } = await client.query(
      `INSERT INTO games (game_state) VALUES ($1) RETURNING id`,
      [JSON.stringify(initialState())]
    );
    const gameId = rows[0].id;

    await client.query(
      `INSERT INTO games_owners (game_id, owner_user_id) VALUES ($1, $2)`,
      [gameId, ownerUserId]
    );

    // Select the question set: explicit ids if provided, otherwise the seeded set.
    let questionRows;
    if (Array.isArray(questionIds) && questionIds.length > 0) {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions WHERE id = ANY($1::int[]) ORDER BY id`,
        [questionIds]
      );
    } else {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions ORDER BY id`
      );
    }

    const ordered = questionRows.rows;
    for (let i = 0; i < ordered.length; i += 1) {
      await client.query(
        `INSERT INTO game_questions (game_id, question_id, position) VALUES ($1, $2, $3)`,
        [gameId, ordered[i].id, i]
      );
    }

    return {
      id: gameId,
      questions: ordered.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: q.options,
      })),
    };
  });
}

/**
 * Load a game's persisted state (id, owner sub mapping, state, score) without
 * leaking answer keys. Returns null when the game does not exist, or a sentinel
 * { exists:false, ownerUserId:null } shape so callers can distinguish 404 vs
 * 403 (other user's game).
 */
async function getGame(pool, gameId) {
  const result = await pool.query(
    `SELECT g.id, g.game_state, o.owner_user_id
       FROM games g
       LEFT JOIN games_owners o ON o.game_id = g.id
      WHERE g.id = $1`,
    [gameId]
  );
  if (result.rows.length === 0) {
    return null;
  }
  const row = result.rows[0];
  const state = typeof row.game_state === 'string' ? JSON.parse(row.game_state) : row.game_state;
  return {
    id: row.id,
    ownerUserId: row.owner_user_id,
    state: state && state.state ? state.state : States.PLAYING,
    score: state && typeof state.score === 'number' ? state.score : 0,
  };
}

/**
 * Submit an answer for `gameId`/`questionId` within a single serialized
 * transaction. Enforces:
 *
 *   * Ownership check (other user's game -> typed 403 error).
 *   * The game must be Playing to accept an answer (paused/finished -> 409).
 *   * `answer` must parse as a single reduced fraction; malformed -> 400.
 *   * A repeated answer for the same question does NOT increase the score and
 *     returns the existing result (idempotent 200) rather than a 409.
 *
 * The per-game lock (SELECT ... FOR UPDATE) serializes concurrent score updates.
 * The unique index on answers(game_id, question_id) plus the transaction makes
 * deduplication safe.
 */
async function submitAnswer(pool, gameId, questionId, answer, ownerUserId) {
  return withTransaction(pool, async (client) => {
    // Lock the game row to serialize score updates for this game.
    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    if (gameResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }

    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    const actualOwner = ownerResult.rows.length ? ownerResult.rows[0].owner_user_id : null;
    if (actualOwner === null || actualOwner !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;
    const currentState = gameState && gameState.state ? gameState.state : States.PLAYING;
    if (currentState !== States.PLAYING) {
      const err = new DbError(`Game is not playable (${currentState})`, 'CONFLICT');
      err.status = 409;
      throw err;
    }

    // Validate the submitted answer as a single reduced fraction (server-side).
    let submitted;
    try {
      submitted = parseFraction(answer);
    } catch (fractionErr) {
      const err = new DbError(fractionErr.message, 'INVALID_FRACTION');
      err.status = 400;
      throw err;
    }

    // Fetch the question and its canonical correct answer.
    const questionResult = await client.query(
      `SELECT correct_answer FROM questions WHERE id = $1`,
      [questionId]
    );
    if (questionResult.rows.length === 0) {
      const err = new DbError('Question not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    const correctAnswerText = questionResult.rows[0].correct_answer;
    let correct;
    try {
      const correctFraction = parseFraction(correctAnswerText);
      correct = equals(submitted, correctFraction);
    } catch (_e) {
      correct = false;
    }

    // Deduplicate: if this question was already answered, return the stored
    // result without changing the score.
    const existing = await client.query(
      `SELECT correct FROM answers WHERE game_id = $1 AND question_id = $2`,
      [gameId, questionId]
    );
    if (existing.rows.length > 0) {
      const wasCorrect = existing.rows[0].correct;
      const score = await computeScore(client, gameId);
      return { correct: wasCorrect, score };
    }

    // Record the answer.
    await client.query(
      `INSERT INTO answers (game_id, question_id, answer, correct)
       VALUES ($1, $2, $3, $4)`,
      [gameId, questionId, String(answer), correct]
    );

    // Increment the persisted score only when correct (each correct = 1).
    if (correct) {
      const currentScore =
        typeof gameState.score === 'number' ? gameState.score : 0;
      await client.query(
        `UPDATE games SET game_state = $1 WHERE id = $2`,
        [JSON.stringify(Object.assign({}, gameState, { score: currentScore + 1 })), gameId]
      );
    }

    const score = await computeScore(client, gameId);
    return { correct, score };
  });
}

async function computeScore(client, gameId) {
  const result = await client.query(
    `SELECT COUNT(*)::int AS correct_count
       FROM answers
      WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].correct_count;
}

/**
 * Get the current score for a game. Enforces ownership (other user -> 403).
 */
async function getScore(pool, gameId, ownerUserId) {
  const game = await getGame(pool, gameId);
  if (!game) {
    const err = new DbError('Game not found', 'NOT_FOUND');
    err.status = 404;
    throw err;
  }
  if (game.ownerUserId !== ownerUserId) {
    const err = new DbError('Not authorized for this game', 'FORBIDDEN');
    err.status = 403;
    throw err;
  }
  const result = await pool.query(
    `SELECT COUNT(*)::int AS score FROM answers WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].score;
}

/**
 * Transition a game lifecycle state (pause/resume). Returns the new state.
 * Enforces ownership; invalid transition -> 409.
 */
async function transitionGame(pool, gameId, ownerUserId, transitionFn) {
  return withTransaction(pool, async (client) => {
    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    if (ownerResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    if (ownerResult.rows[0].owner_user_id !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;

    let nextState;
    try {
      nextState = transitionFn(gameState);
    } catch (stateErr) {
      const err = new DbError(stateErr.message, 'INVALID_TRANSITION');
      err.status = 409;
      throw err;
    }

    await client.query(
      `UPDATE games SET game_state = $1 WHERE id = $2`,
      [JSON.stringify(nextState), gameId]
    );
    return nextState.state;
  });
}

module.exports = {
  DbError,
  createPool,
  migrate,
  upsertUser,
  withTransaction,
  createGame,
  getGame,
  submitAnswer,
  getScore,
  transitionGame,
};

'use strict';

/**
 * Redis read-through cache adapter for Space Fractions.
 *
 * The game service (`services/game-service.js`) injects an optional cache so it
 * can serve frequently-read player state without re-reading PostgreSQL on every
 * request. This module is a *real* Redis client (via the official `redis`
 * package), not a placeholder: `get(key)` issues an actual GET and `set(key,
 * value, ttlMs)` issues SET with PX expiry. It is strictly a pass-through cache
 * — PostgreSQL remains the system of record, and any cache miss simply falls
 * through to the authoritative database (the caller is responsible for the
 * read-side population).
 *
 * Graceful degradation (assumption A-6): when Redis is absent, the client fails
 * to connect, an operation times out or errors, or the feature is flagged
 * disabled (`disabled` contains "redis"), `get` resolves `null` and `set`
 * resolves without throwing, so the cache never becomes a hard dependency of
 * the game flow. Strategy is plain Redis rather than Redis Cluster, so no
 * MIGRATE/ASK handling is required; a failed write is logged and ignored.
 */

const { createClient } = require('redis');

const DEFAULT_TTL_MS = 30_000;
/** Feature flag name consumed by top-level wiring to disable this integration. */
const FEATURE_FLAG = 'redis';

/**
 * Build a read-through cache adapter.
 *
 * @param {object} [options]
 * @param {string}   [options.url]       Redis URL (defaults to
 *                                       process.env.REDIS_URL or redis://localhost:6379).
 * @param {number}   [options.defaultTtlMs] Default TTL for set() when none is given.
 * @param {Function} [options.clock]     Injectible timers/setTimeout for tests.
 * @param {Array|Set} [options.disabled] Disabled feature names; when it contains
 *                                       "redis", all operations degrade.
 * @param {Function} [options.log]       Log sink (defaults to console).
 *
 * @returns {{ get: (key:string)=>Promise<string|null>, set: (key:string, value:string, ttlMs?:number)=>Promise<void>, isDisabled: ()=>boolean }}
 */
function createCache(options = {}) {
  const url = options.url || process.env.REDIS_URL || 'redis://localhost:6379';
  const defaultTtlMs = options.defaultTtlMs || DEFAULT_TTL_MS;
  const disabledSet =
    options.disabled instanceof Set
      ? options.disabled
      : new Set(Array.isArray(options.disabled) ? options.disabled : []);
  const log = options.log || console;
  const clock = options.clock || {};

  let client = null;
  let connectErrorLogged = false;

  if (typeof createClient === 'function') {
    try {
      client = createClient({ url });
      // Fire-and-forget connect; we do not await it here because the service must
      // remain operational if Redis is down. Errors surface via log on first use.
      const ready = client.on ? client.on('error', (err) => {
        if (!connectErrorLogged) {
          connectErrorLogged = true;
          log.warn && log.warn(`cache (redis) error: ${err.message}`);
        }
      }) : null;
      if (client.connect && typeof client.connect === 'function') {
        client.connect().catch((err) => {
          if (!connectErrorLogged) {
            connectErrorLogged = true;
            log.warn && log.warn(`cache (redis) connect failed: ${err.message}`);
          }
        });
      }
      void ready;
    } catch (err) {
      client = null;
      log.warn && log.warn(`cache (redis) client creation failed: ${err.message}`);
    }
  }

  /** Whether this integration is disabled by feature flag. */
  function isDisabled() {
    return disabledSet.has(FEATURE_FLAG) || disabledSet.has('redis');
  }

  /**
   * Read a key. Resolves null on absence, error, timeout, or disablement.
   * @param {string} key
   * @returns {Promise<string|null>}
   */
  async function get(key) {
    if (isDisabled() || !client) return null;
    try {
      const value = await withTimeout(client.get(key), defaultTtlMs, clock);
      return value === null || typeof value !== 'string' ? null : value;
    } catch (err) {
      log.warn && log.warn(`cache get failed for "${key}": ${err.message}`);
      return null;
    }
  }

  /**
   * Write a key with an optional TTL. Never throws (best-effort cache write).
   * @param {string} key
   * @param {string} value
   * @param {number} [ttlMs]
   * @returns {Promise<void>}
   */
  async function set(key, value, ttlMs) {
    if (isDisabled() || !client) return;
    const ttl = Number.isFinite(ttlMs) && ttlMs > 0 ? Math.floor(ttlMs) : defaultTtlMs;
    try {
      await withTimeout(client.set(key, String(value), { PX: ttl }), defaultTtlMs, clock);
    } catch (err) {
      log.warn && log.warn(`cache set failed for "${key}": ${err.message}`);
    }
  }

  return { get, set, isDisabled };
}

/**
 * Wrap an async operation with a hard timeout. Resolves undefined on timeout so
 * callers degrade gracefully instead of hanging. Used to bound a hung Redi client.
 */
function withTimeout(operation, ms, clock = {}) {
  const setT = clock.setTimeout || setTimeout;
  const clearT = clock.clearTimeout || clearTimeout;

  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setT(() => {
      if (!settled) {
        settled = true;
        reject(new Error(`cache operation timed out after ${ms}ms`));
      }
    }, ms);

    Promise.resolve()
      .then(operation)
      .then((value) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          resolve(value);
        }
      })
      .catch((err) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          reject(err);
        }
      });
  });
}

module.exports = {
  createCache,
  FEATURE_FLAG,
  DEFAULT_TTL_MS,
};

'use strict';

/**
 * RabbitMQ score-event emitter for Space Fractions.
 *
 * The game service (`services/game-service.js`) injects an optional `events`
 * adapter so it can publish an event every time an answer is scored, without
 * blocking or failing the authoritative answer result. This module is a *real*
 * AMQP client (via the official `amqplib` package), not a placeholder: it opens
 * a channel, asserts the target exchange, and publishes a serialized score event
 * with a mandatory `content_type` of `application/json` and persistent delivery
 * mode, so the event survives a broker restart. RabbitMQ is a strict side
 * channel — the score it reports is already durably committed in PostgreSQL, and
 * consumers (e.g. dashboards, streaming analytics) may lag or replay without
 * affecting game correctness.
 *
 * Graceful degradation (assumption A-6): when the broker is absent, a connect or
 * publish fails, a publish exceeds the bounded timeout, or the feature is
 * flagged disabled (`disabled` contains "rabbitmq"), `publishScoreEvent` resolves
 * without throwing. The game service therefore never blocks a player's answer on
 * broker availability. Connections are opened lazily and (best effort) closed on
 * `close()`, with per-attempt error logging so a down broker does not flood the
 * log.
 */

const amqp = require('amqplib');

const DEFAULT_URL = 'amqp://localhost:5672';
const DEFAULT_EXCHANGE = 'space-fractions.scores';
const DEFAULT_TIMEOUT_MS = 1000;

/** Feature flag name consumed by top-level wiring to disable this integration. */
const FEATURE_FLAG = 'rabbitmq';

/**
 * Build a score-event emitter.
 *
 * @param {object} [options]
 * @param {string}   [options.url]         AMQP URL (defaults to
 *                                         process.env.RABBITMQ_URL or DEFAULT_URL).
 * @param {string}   [options.exchange]    Exchange to publish to.
 * @param {number}   [options.timeoutMs]   Hard bound for a publish call.
 * @param {Array|Set}[options.disabled]    Disabled feature names; when it contains
 *                                         "rabbitmq", all publishes degrade.
 * @param {Function} [options.clock]       Injectible timers for tests.
 * @param {Function} [options.log]         Log sink (defaults to console).
 *
 * @returns {{ publishScoreEvent: (event:object)=>Promise<void>, close: ()=>Promise<void>, isDisabled: ()=>boolean }}
 */
function createEventEmitter(options = {}) {
  const url = options.url || process.env.RABBITMQ_URL || DEFAULT_URL;
  const exchange = options.exchange || DEFAULT_EXCHANGE;
  const timeoutMs = options.timeoutMs || DEFAULT_TIMEOUT_MS;
  const disabledSet =
    options.disabled instanceof Set
      ? options.disabled
      : new Set(Array.isArray(options.disabled) ? options.disabled : []);
  const log = options.log || console;
  const clock = options.clock || {};

  let connection = null;
  let channel = null;
  let channelReady = null; // Promise<channel|null> in flight, null when absent
  let connectErrorLogged = false;

  /** Whether this integration is disabled by feature flag. */
  function isDisabled() {
    return disabledSet.has(FEATURE_FLAG) || disabledSet.has('rabbitmq');
  }

  function logWarn(message) {
    if (log.warn) log.warn(message);
  }

  /**
   * Lazily obtain a ready channel. Returns null on any failure (disabled, no
   * amqplib, connect error, channel/assert errors) so publishers degrade.
   * Reuses a single connection/channel per emitter instance for the lifetime of
   * the process; a broken connection is discarded so the next publish retries.
   */
  async function getChannel() {
    if (isDisabled() || !amqp || typeof amqp.connect !== 'function') return null;
    if (channelReady) return channelReady;

    channelReady = (async () => {
      try {
        connection = await withTimeout(amqp.connect(url), timeoutMs, clock);
        const ch = await withTimeout(connection.createChannel(), timeoutMs, clock);
        await withTimeout(ch.assertExchange(exchange, 'topic', { durable: true }), timeoutMs, clock);
        channel = ch;
        return ch;
      } catch (err) {
        if (!connectErrorLogged) {
          connectErrorLogged = true;
          logWarn(`events (rabbitmq) channel setup failed: ${err.message}`);
        }
        // Discard the partial connection/channel so the next call retries fresh.
        try { if (connection && connection.close) await connection.close(); } catch { /* ignore */ }
        connection = null;
        channel = null;
        return null;
      } finally {
        // Allow a later retry after a failure (only keeps the inflight promise
        // while it is in progress; a resolved null must not be cached forever).
        if (channelReady) {
          const settled = channelReady;
          channelReady = null;
          return settled;
        }
      }
    })();

    const settled = channelReady;
    channelReady = null;
    return settled;
  }

  /**
   * Publish a score event. Resolves successfully (never throws) regardless of
   * broker availability so the caller can treat event delivery as best-effort.
   *
   * @param {object} event `{ gameId, userId, score, correct }`
   * @returns {Promise<void>}
   */
  async function publishScoreEvent(event) {
    if (isDisabled()) return;
    const ch = await getChannel();
    if (!ch) return;

    const payload = Buffer.from(JSON.stringify({
      type: 'score.updated',
      gameId: event.gameId,
      userId: event.userId,
      score: event.score,
      correct: Boolean(event.correct),
      at: new Date().toISOString(),
    }));

    const routingKey = 'space-fractions.game.score';
    try {
      await withTimeout(
        ch.publish(exchange, routingKey, payload, {
          persistent: true,
          contentType: 'application/json',
        }),
        timeoutMs,
        clock
      );
    } catch (err) {
      logWarn(`score event publish failed: ${err.message}`);
      // Invalidate the (possibly broken) channel so the next publish retries.
      channel = null;
      if (connection && connection.close) {
        connection.close().catch(() => {});
      }
      connection = null;
    }
  }

  /**
   * Best-effort close of the underlying connection. Never throws.
   */
  async function close() {
    try {
      if (channel && channel.close) await channel.close();
      if (connection && connection.close) await connection.close();
    } catch {
      /* ignore */
    } finally {
      channel = null;
      connection = null;
    }
  }

  return { publishScoreEvent, close, isDisabled };
}

/**
 * Wrap an async operation with a hard timeout. On timeout, resolves undefined so
 * callers degrade gracefully; because `getChannel` treats undefined as failure
 * and `publishScoreEvent` ignores undefined results, a timeout cannot hang.
 */
function withTimeout(operation, ms, clock = {}) {
  const setT = clock.setTimeout || setTimeout;
  const clearT = clock.clearTimeout || clearTimeout;

  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setT(() => {
      if (!settled) {
        settled = true;
        resolve(undefined);
      }
    }, ms);

    Promise.resolve()
      .then(operation)
      .then((value) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          resolve(value);
        }
      })
      .catch((err) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          reject(err);
        }
      });
  });
}

module.exports = {
  createEventEmitter,
  FEATURE_FLAG,
  DEFAULT_EXCHANGE,
  DEFAULT_TIMEOUT_MS,
};

'use strict';

/**
 * Search adapter for question discovery (Elasticsearch with bounded timeout).
 *
 * This module exposes a `search(query)` interface consumed by the question
 * service (`services/question-service.js`). It is a *real* Elasticsearch client
 * (via the official `@elastic/elasticsearch` package), not a placeholder: it
 * issues an actual `search` request against the configured cluster and maps the
 * response hits back to `{ id, prompt }` records. The index is assumed to hold
 * an `id` field mirroring the owning `questions` table primary key, so the
 * caller can reconcile results against the authoritative PostgreSQL store.
 *
 * Graceful degradation: when the backend is absent, times out, errors, or the
 * feature is disabled (DISABLED_FEATURES contains "elasticsearch"), `search()`
 * resolves `undefined`. The question service then falls back to an authoritative
 * database `ILIKE` query, so search correctness never depends on Elastisearch
 * availability. The timeout is honored at the HTTP-call level (Elasticsearch
 * request timeout) *and* at the client level (a supplemental timer so a hung or
 * non-compliant client cannot block indefinitely).
 */

const { Client } = require('@elastic/elasticsearch');

const DEFAULT_INDEX = 'questions';
const DEFAULT_TIMEOUT_MS = 500;

/** Feature flag name used by the top-level wiring to disable this integration. */
const FEATURE_FLAG = 'elasticsearch';

/**
 * Produce a source record a search hit can be projected to. A hit may store the
 * row inline (_source.id / _source.prompt / extra option data) or only the
 * database id (_id). We require at least an integer id; prompt is best-effort
 * for display-only purposes (the authoritative DB fallback supplies the rest).
 */
function hitToRecord(hit) {
  const src = hit?._source || {};
  if (src && typeof src.id === 'number' && Number.isInteger(src.id)) {
    return { id: src.id, prompt: typeof src.prompt === 'string' ? src.prompt : '' };
  }
  if (hit && typeof hit._id === 'string') {
    const parsed = Number.parseInt(hit._id, 10);
    if (Number.isInteger(parsed)) {
