  byId('start-game-btn').addEventListener('click', () => startGame().catch(() => {}));
  byId('answer-form').addEventListener('submit', (ev) => submitAnswer(ev).catch(() => {}));
  byId('pause-btn').addEventListener('click', () => pauseGame().catch(() => {}));
