  // Admin CRUD is only reachable by admins; hide the admin form for non-admins.
  const adminScreen = byId('screen-admin');
  if (!adminScreen) return;
  if (isAdminUser()) {
    adminScreen.hidden = false;
  } else {
    adminScreen.hidden = true;
  }
