  font-size: 3rem;
  font-weight: 700;
  color: var(--warning);
  margin: 0 0 12px;
}

/* Admin screen */
.admin-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.admin-form label {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 6px;
}

.question-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.question-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  background: var(--space-panel);
  border: 1px solid var(--space-border);
  border-radius: 8px;
}

/* Errors */
.error {
  color: var(--danger);
  margin-top: 12px;
  font-weight: 600;
}

/* Help panel */
.help-panel {
  margin-top: 20px;
  padding: 14px 16px;
  background: var(--space-panel);
  border: 1px solid var(--space-border);
  border-radius: 8px;
}

.help-panel h2 {
  margin: 0 0 8px;
  font-size: 1.1rem;
}

.help-panel ul {
  margin: 0;
  padding-left: 20px;
}

@media (max-width: 560px) {
  .shell {
    padding: 16px 14px 48px;
  }

  .topbar h1 {
    font-size: 1.3rem;
  }

  .prompt {
    font-size: 1.2rem;
  }
}"}

