  "dependencies": {
    "@elastic/elasticsearch": "8.13.1",
    "amqplib": "0.10.4",
    "express": "4.19.2",
    "jose": "5.2.4",
    "pg": "8.11.5",
    "prom-client": "15.1.2",
    "redis": "4.6.13"
  },
  "devDependencies": {
    "js-yaml": "4.1.0"
  },
  "license": "UNLICENSED"
}

